"""Prepare a candidate display payload from explicitly supplied local artifacts. No network."""
from pathlib import Path
import argparse,json,sqlite3,hashlib
p=argparse.ArgumentParser(description=__doc__)
for name in ['reference-db','education-candidate','health-candidate','health-summary','migration-candidate','out']:
 p.add_argument('--'+name,type=Path,required=True)
a=p.parse_args()
D=sqlite3.connect(a.reference_db.resolve().as_uri()+'?mode=ro',uri=True)
names={x[0]:x[1].title() for x in D.execute("SELECT geo_code,geo_name FROM observations WHERE view_type='MAPA' GROUP BY geo_code")};D.close();names['02']='CABA';names['94']='Tierra del Fuego';names['00']='Total urbano nacional'
edu=json.loads(a.education_candidate.read_text());erows=[r for r in edu['observations'] if r['level']=='primary' and r['grade_system']=='total' and r['geo_level']=='province']
periods=sorted({r['period_label'] for r in erows},reverse=True)
health=json.loads(a.health_candidate.read_text());healthsum=json.loads(a.health_summary.read_text());mig=json.loads(a.migration_candidate.read_text());mr=[r for r in mig if r['missing_policy']=='show_unknown' and r['age_policy']=='all'];geos=sorted(names.keys()-{'00'})
catalog={
 'education':{'title':'Abandono escolar primario','question':'¿Cómo varía entre provincias?','theme':'Educación y cuidado','snapshot':'2026-11-06','release':edu['metadata']['source_sha256'],'periods':periods,'domain':'province','geos':geos,'universes':['primary_total'],'universeLabel':'Educación común · nivel primario · total provincial','periodLabel':'Ciclo lectivo del cuadro','unit':'%','measure':'rate','source':'Secretaría de Educación · tasa de abandono interanual','sourceURL':edu['metadata']['source_url'],'sourceDetail':'Planilla oficial 2025–2012, división político-territorial. El año se expresa como ciclo, no como año aislado de carga.','status':'Candidato técnico · aprobación temática pendiente','note':'Las tasas negativas se conservan: el modelo de flujo puede producirlas por movimientos o reincorporaciones de estudiantes. No se recortan a cero.','blocking':'La fuente oficial tiene períodos explícitos. Persisten conflictos de etiquetas con la copia histórica de Tableau; esta vista no aprueba su sustitución automática.','rows':[{'geo':r['geo_code'],'name':r['geo_name'].strip(),'period':r['period_label'],'universe':'primary_total','value':r['value'],'cellStatus':r['cell_status'],'sourceRow':r['source_row'],'sourceColumn':r['source_column']} for r in erows]},
 'health':{'title':'Nacidos vivos por provincia','question':'¿Cuántos nacimientos se registraron?','theme':'Salud','snapshot':'2026-11-06','release':healthsum['sha256']['births'],'periods':['2024'],'domain':'province','geos':geos,'universes':['births_residence'],'universeLabel':'Nacidos vivos registrados · provincia de residencia','periodLabel':'Año del cuadro','unit':'nacidos vivos','measure':'count','source':'DEIS · CSV de nacidos vivos 2024','sourceURL':'https://www.argentina.gob.ar/sites/default/files/2021/03/datos_sobre_nacidos_vivos_2024.csv','sourceDetail':'Datos agregados por provincia de residencia. Códigos98 y99 no se convierten en provincias; no se calcula aquí un total nacional a partir del mapa.','status':'Candidato técnico · aprobación temática pendiente','note':'Se muestran cantidades, no tasas de natalidad ni riesgo. Una provincia con más nacimientos no tiene por eso una mayor tasa.','blocking':'La conciliación del adaptador no equivale a aprobación institucional ni a validación de todas las vistas de salud.','rows':[{'geo':r['province_code'],'name':names[r['province_code']],'period':'2024','universe':'births_residence','value':r['births'],'cellStatus':'observed'} for r in health['aggregates'] if r['map_eligible']]},
 'migration':{'title':'Lugar de nacimiento de la población urbana','question':'¿Cómo se compone la población?','theme':'Grupos prioritarios','snapshot':'2026-11-06','release':'EPHU-2025-T3-show_unknown-all-review','periods':['2025-T3'],'domain':'national','geos':['00'],'universes':['all'],'universeLabel':'Población total urbana · todas las edades · EPH total urbano','periodLabel':'Período de encuesta','unit':'%','measure':'proportion','source':'INDEC · EPH total urbano 2025, tercer trimestre','sourceURL':'https://www.indec.gob.ar/Institucional/Indec/BasesDeDatos','sourceDetail':'Reprocesamiento candidato del adaptador social: ponderador y respuestas sin información conservados. No se sustituyó por EPH de31aglomerados.','status':'Bloqueado para sustitución · conciliación pendiente','note':'La copia de Tableau suma101% en tres categorías. Esta vista muestra el cálculo candidato incluyendo sin información; no reemplaza ni normaliza los valores de Tableau.','blocking':'Hay diferencias entre la fuente reprocesada y la copia de Tableau. Se requiere resolver universo, ponderación y edición antes de publicar una sustitución.','rows':[{'geo':'00','name':r['label'],'category':r['category'],'period':'2025-T3','universe':'all','value':r['value'],'numerator':r['numerator'],'denominator':r['denominator'],'cellStatus':'candidate_unapproved','tableau':{'same_province':87.3,'other_province':10.1,'foreign_country':3.6}.get(r['category'])} for r in mr]}
}
P={'catalog':catalog,'names':names,'mapGate':{'status':'blocked_geometry_review','reason':'La revisión GIS detectó geometrías inválidas y superposiciones en el recurso simplificado. No se presenta un mapa como validado. La selección territorial sigue disponible mediante lista y barras.','candidate':True}}

a.out.parent.mkdir(parents=True,exist_ok=True)
a.out.write_text(json.dumps(P,ensure_ascii=False,indent=2),encoding='utf-8')
roles={k:getattr(a,k) for k in ['reference_db','education_candidate','health_candidate','health_summary','migration_candidate']}
provenance={'status':'prepared_candidate_not_approved','network_requests_required':False,'input_sha256':{k:hashlib.sha256(v.read_bytes()).hexdigest() for k,v in roles.items()},'output_sha256':hashlib.sha256(a.out.read_bytes()).hexdigest(),'scope':'same frozen prototype catalog; no automatic adoption of new schemas or periods'}
a.out.with_name(a.out.stem+'_provenance.json').write_text(json.dumps(provenance,ensure_ascii=False,indent=2),encoding='utf-8')
print(a.out)
